DO $preflight$ DECLARE fn pg_proc%rowtype;owner_oid oid;at_time timestamptz:=clock_timestamp();epoch timestamptz;BEGIN
 SELECT oid INTO owner_oid FROM pg_roles WHERE rolname=current_user;
 SELECT * INTO fn FROM pg_proc WHERE oid='fsrs_private.admission_contract_hash()'::regprocedure;
 IF md5(fn.prosrc)<>'ef7227c3f7d3ff47760d9ce06c844231' OR fn.proowner<>owner_oid OR fn.proconfig IS DISTINCT FROM ARRAY['search_path=""']::text[] OR NOT fn.prosecdef OR has_function_privilege('anon',fn.oid,'EXECUTE') OR has_function_privilege('authenticated',fn.oid,'EXECUTE') OR has_function_privilege('service_role',fn.oid,'EXECUTE') THEN RAISE EXCEPTION 'learning022_checker_drift';END IF;
